function getCompassLabel(
  idx: number,
  playerCount?: number,
  /** Место на экране важнее индекса: в 3p idx1 справа — «Восток», не «Север». */
  seatPosition?: 'left' | 'right' | 'top' | 'bottom',
): 'Юг' | 'Север' | 'Запад' | 'Восток' {
  if (seatPosition) {
    switch (seatPosition) {
      case 'bottom':
        return 'Юг';
      case 'top':
        return 'Север';
      case 'left':
        return 'Запад';
      case 'right':
        return 'Восток';
    }
  }
  /** 3p без position: idx1 = Восток (как на ПК). */
  if (playerCount === 3) {
    switch (idx) {
      case 0:
        return 'Юг';
      case 1:
        return 'Восток';
      case 2:
        return 'Запад';
      default:
        return 'Юг';
    }
  }
  switch (idx) {
    case 0:
      return 'Юг';
    case 1:
      return 'Север';
    case 2:
      return 'Запад';
    case 3:
      return 'Восток';
    default:
      return 'Юг';
  }
}

