/** sessionStorage: сдвиг бейджа по X в short + immersive (px от центра). */
const MOBILE_SHORT_IMMERSIVE_BADGE_DRAG_X_KEY = 'upd.gameTable.mobileShortImmersiveBadgeDragX.v1';

function readImmersiveBadgeDragXFromStorage(): number {
  if (typeof window === 'undefined') return 0;
  try {
    const raw = sessionStorage.getItem(MOBILE_SHORT_IMMERSIVE_BADGE_DRAG_X_KEY);
    if (raw == null || raw === '') return 0;
    const n = Number(raw);
    return Number.isFinite(n) ? n : 0;
  } catch {
    return 0;
  }
}

/** Центр бейджа = vw/2 + offset; не даём уехать за края с margin. */
function clampImmersiveBadgeDragX(offset: number, badgeWidthPx: number, viewportWidthPx: number, edgeMarginPx: number): number {
  const half = viewportWidthPx / 2 - badgeWidthPx / 2 - edgeMarginPx;
  const max = Math.max(0, half);
  if (max === 0) return 0;
  if (offset > max) return max;
  if (offset < -max) return -max;
  return offset;
}

/** Внутри этой зоны по X бейдж «прилипает» к центру (offset 0), пока жест не «сорван» порогом escape. */
const IMMERSIVE_BADGE_SNAP_ZONE_PX = 16;
/** Если палец уводит сырой offset дальше — магнит отключается до конца жеста (можно зафиксировать чуть в стороне от центра). */
const IMMERSIVE_BADGE_MAGNET_ESCAPE_PX = 40;

/** Макс. высота зоны магнита от низа скролла (px). Шире — доводка срабатывает выше по странице, доходит до immersive без «недотяга». */
const SHORT_VH_MAGNET_ZONE_CAP_PX = 188;
/**
 * Если включена ручная растяжка Юга (shortVhSouthStretchPx), контент выше — без сужения зоны
 * immersive срабатывает за сотни px до реального низа: не докрутить до нижней границы панели/ручки.
 */
const SHORT_VH_MAGNET_ZONE_WHEN_SOUTH_STRETCH_SCALE = 0.22;
const SHORT_VH_MAGNET_ZONE_WHEN_SOUTH_STRETCH_CAP_PX = 56;
/** Минимальный ход скролла, при котором включаем магнит (иначе на коротком контенте дёргает). */
const SHORT_VH_MAGNET_MIN_SCROLL_RANGE_PX = 48;
/**
 * Обратный магнит (выход из immersive): по расстоянию от прижатого низа (maxTop − scrollTop) и/или по жесту
 * «вниз» с нижней части экрана — дотягиваем к виду «под шапкой»: scrollTop=0, шапка снова в потоке над столом.
 * Порог по скроллу — минимум из «половина высоты шапки» и доли maxTop (чтобы срабатывало даже при капризном scroll).
 */
const SHORT_VH_REVERSE_MAGNET_HALF_HEADER_MIN_PX = 28;
const SHORT_VH_REVERSE_MAGNET_HALF_HEADER_MAX_PX = 84;
/** Зона «чипа» приглашения в immersive: не при самом нуле distBottom. */
const SHORT_VH_IMMERSIVE_EXIT_SCROLL_PX = 16;
/**
 * Short immersive: верх visual viewport — старт жеста «вниз» здесь почти всегда pull-to-refresh страницы.
 * Не ставим touchmove-выход в шапку (иначе при обновлении страницы одновременно раскрывается хедер).
 */
const SHORT_IMMERSIVE_PULL_REFRESH_GUARD_TOP_PX = 100;
/** Сброс shortVhMagnetConsumedRef при прокрутке к верху: порог относительно зоны (px). */
const SHORT_VH_MAGNET_REARM_THRESHOLD_PX = 8;
/** Если !immersive и consumed «залип» после выхода — разрешаем прямой магнит снова, когда палец снова в зоне снизу или ушёл от неё. */
const SHORT_VH_MAGNET_REARM_LEAVE_BOTTOM_EXTRA_PX = 24;
/** Иммерсив: считаем wrap «прижатым к низу», если до maxTop не больше этого px — иначе сброс margin С/З дёргал вёрстку из‑за субпикселей/WebKit. */
const SHORT_VH_IMMERSIVE_NW_ALIGN_SCROLL_SLACK_PX = 28;
/** Иммерсив: margin-top ряда З/С относительно верха бейджа — clamp |margin| (двустороннее выравнивание). */
const SHORT_VH_IMMERSIVE_NW_ALIGN_MARGIN_ABS_MAX_PX = 40;
/**
 * Если wrap был у низа, а высота контента выросла (ваш ход, рамка, ряд карт), dist до низа станет > slack, но небольшим.
 * Тогда переприжимаем scroll к низу, а не сбрасываем выравнивание С/З (иначе зазор сверху и обрез низа панели Юга).
 */
const SHORT_VH_IMMERSIVE_REPIN_AFTER_GROW_MAX_DIST_PX = 240;
/** Южная ручка short-VH: сдвиг меньше этого (по Y) — тап → меню режимов; иначе перетаскивание → прокрутка столика. */
const SHORT_VH_SOUTH_PULL_TAB_TAP_MAX_MOVE_PX = 14;
/** После отпускания ручки без удержания — глушим авто-immersive от нижнего магнита (микроскролл от короткого тапа). */
const SHORT_VH_SOUTH_PULL_TAB_POST_TAP_MAGNET_SUPPRESS_MS = 650;
function readShortGameHeaderHalfHeightPx(headerEl: HTMLElement | null): number {
  if (headerEl == null) return 44;
  const h = headerEl.offsetHeight > 8 ? headerEl.offsetHeight : headerEl.getBoundingClientRect().height;
  const half = h > 12 ? Math.round(h / 2) : 44;
  return Math.max(
    SHORT_VH_REVERSE_MAGNET_HALF_HEADER_MIN_PX,
    Math.min(SHORT_VH_REVERSE_MAGNET_HALF_HEADER_MAX_PX, half),
  );
}

/** Глиф кнопки «Показать шапку» (immersive, внутри бейджа): один ряд из 5 кружков; цвет в --dot. */
