const LAST_TRICK_REVEAL_MS = LAST_TRICK_REVEAL_MS_SHARED;
/** Пауза с картами на столе (ещё без оверлея). */
const LAST_TRICK_CARDS_PAUSE_MS = LAST_TRICK_CARDS_PAUSE_MS_SHARED;
/** Длительность полёта карт к слоту победителя. */
const LAST_TRICK_COLLECT_MS = LAST_TRICK_COLLECT_MS_SHARED;
/** Пауза с миганием панельки взявшего взятку (+ старт оверлея). */
const LAST_TRICK_WINNER_PAUSE_MS = LAST_TRICK_WINNER_PAUSE_MS_SHARED;
/** Пауза только на умные «Итого» (running-total) до начала схлопывания. */
const DEAL_RESULTS_TOTALS_ACCENT_MS = DEAL_RESULTS_TOTALS_ACCENT_MS_SHARED;
/** Длительность фазы «таблица сворачивается в кнопку» */
const DEAL_RESULTS_COLLAPSING_MS = DEAL_RESULTS_COLLAPSING_MS_SHARED;
/** Пауза до следующей раздачи (offline / v1 host); v2 сервер = DEAL_COMPLETE_HOLD_MS. */
const TRICK_PAUSE_MS = DEAL_COMPLETE_HOLD_MS;

/** Задержка бейджа «ждём вашу карту» в слоте Юга после начала хода. */
const HUMAN_TRICK_WAIT_BADGE_DELAY_MS = 2500;

/** После rotateState индексы display образуют тот же круг, что у Юга — ходим playerAtLeftFrom как в офлайне. */
function getTrickPlayerIndex(
  trickLeaderIndex: number,
  cardIndex: number,
  playerCount: PlayerCount = 4,
): number {
  return playerAtLeftFrom(trickLeaderIndex, cardIndex, playerCount);
}

/**
 * After-short phone LS: карты на сукне −10% от обычного phone LS.
 */
const AFTER_SHORT_TRICK_TABLE_CARD_SCALE_MUL = 0.9;
/** Моб. кольцо заказа (оппоненты): padding с каждой стороны; phone LS — ×0.5, лицо +этот px. */
const MOBILE_OPP_ORDER_RING_PAD_PX = 6;
/** Моб. Юг · exact / chasing кольцо. */
const MOBILE_USER_ORDER_RING_PAD_EXACT_PX = 5;
const MOBILE_USER_ORDER_RING_PAD_CHASING_PX = 4;

/** Масштаб карт на сукне. ПК: base 1.18 × пользовательский boost карт. */
function getTrickTableCardScale(
  isMobileOrTablet: boolean,
  isMobileLandscape: boolean,
  pcScaleMul = 1,
  /** Планшет · 4p: компакт + бонус при увеличении масштаба стола; мобила не затрагивается. */
  tabletFourPcTableCompact = false,
  tabletTableScalePct = 100,
  /**
   * Mid 601–899: `true` → дефолт; число → точный масштаб от ширины viewport
   * (узкий — меньше, чтобы не наезжать на козырь; широкий — крупнее и ромб по центру).
   * Mid рисует ПК-лицо (tableCardMobile=false, contentScale=undefined).
   */
  isMidLandscape: boolean | number = false,
  /** Phone LS after-short: сжатие карт на столе (mid сюда не передаём). */
  afterShortCompact = false,
): number {
  if (!isMobileOrTablet) {
    let s = 1.18 * pcScaleMul;
    if (tabletFourPcTableCompact) s = tabletFourTableCardScaleWithTablePct(s, tabletTableScalePct);
    return s;
  }
  if (isMobileLandscape) {
    let s: number;
    if (typeof isMidLandscape === 'number') s = isMidLandscape;
    else s = isMidLandscape ? 1.06 : 0.822;
    if (afterShortCompact) s *= AFTER_SHORT_TRICK_TABLE_CARD_SCALE_MUL;
    return s;
  }
  return 0.98;
}

function getTrickTableContentScale(
  isMobileOrTablet: boolean,
  isMobileLandscape: boolean,
  isMidLandscape: boolean | number = false,
  afterShortCompact = false,
): number | undefined {
  if (!isMobileOrTablet) return undefined;
  if (isMobileLandscape) {
    /* Mid: ПК-лицо — contentScale = scale (undefined → CardView cs=scale), иначе мелкие блеклые глифы */
    if (typeof isMidLandscape === 'number' || isMidLandscape) return undefined;
    const cs = 1.32;
    return afterShortCompact ? cs * AFTER_SHORT_TRICK_TABLE_CARD_SCALE_MUL : cs;
  }
  return 1.5;
}

/** Mid 601–899: масштаб карт на сукне от ширины окна (реактивно на resize). */
function midLandscapeTrickCardScaleFromWidth(widthPx: number): number {
  const t = Math.max(0, Math.min(1, (widthPx - 601) / (899 - 601)));
  /* ~0.86 @601 → ~1.18 @899 */
  return Math.round((0.86 + t * 0.32) * 1000) / 1000;
}

function useMidLandscapeTrickCardScale(enabled: boolean): number {
  const [scale, setScale] = useState(() => {
    if (typeof window === 'undefined' || !enabled) return 1.06;
    const w = window.visualViewport?.width ?? window.innerWidth;
    return midLandscapeTrickCardScaleFromWidth(w);
  });
  useEffect(() => {
    if (!enabled) return;
    const sync = () => {
      const w = window.visualViewport?.width ?? window.innerWidth;
      setScale(midLandscapeTrickCardScaleFromWidth(w));
    };
    sync();
    window.addEventListener('resize', sync);
    const vv = window.visualViewport;
    vv?.addEventListener('resize', sync);
    return () => {
      window.removeEventListener('resize', sync);
      vv?.removeEventListener('resize', sync);
    };
  }, [enabled]);
  return scale;
}

