const SCALE_GEAR_PCT_NEUTRAL = '#a5f3fc';
const SCALE_GEAR_PCT_ABOVE = '#f4a628';
const SCALE_GEAR_PCT_BELOW = '#63efc8';

function mixHexTowardWhite(hex: string, t: number): string {
  const n = hex.replace('#', '');
  if (n.length !== 6) return hex;
  const r = parseInt(n.slice(0, 2), 16);
  const g = parseInt(n.slice(2, 4), 16);
  const b = parseInt(n.slice(4, 6), 16);
  const k = Math.max(0, Math.min(1, t));
  const to = (c: number) => Math.round(c + (255 - c) * k);
  return `#${[to(r), to(g), to(b)].map((c) => c.toString(16).padStart(2, '0')).join('')}`;
}

/**
 * Умный цвет % масштаба: 100% — циан; выше — #f4a628 (ярче дальше от 100);
 * ниже — #63efc8 (ярче дальше от 100).
 */
function scaleGearValueTone(pct: number): { color: string; textShadow: string } {
  if (!Number.isFinite(pct) || pct === 100) {
    return {
      color: SCALE_GEAR_PCT_NEUTRAL,
      textShadow: '0 0 8px rgba(34, 211, 238, 0.55)',
    };
  }
  const above = pct > 100;
  const base = above ? SCALE_GEAR_PCT_ABOVE : SCALE_GEAR_PCT_BELOW;
  const bright = Math.min(1, Math.abs(pct - 100) / 12);
  const color = mixHexTowardWhite(base, bright * 0.42);
  const glowAlpha = 0.35 + bright * 0.5;
  const glowBlur = 6 + bright * 10;
  const glow = above
    ? `0 0 ${glowBlur}px rgba(244, 166, 40, ${glowAlpha})`
    : `0 0 ${glowBlur}px rgba(99, 239, 200, ${glowAlpha})`;
  return { color, textShadow: glow };
}

/**
 * Landscape: ромб от правого края.
 * Mid (`centerOnFelt`): half-w от свободной ширины (минус зона козыря слева),
 * чтобы слоты не прятались под козырем в 3p и 4p.
 */
function getTrickLandscapeSlotStyle(
  playerIdx: number,
  base: React.CSSProperties,
  playerCount: PlayerCount = 4,
  centerOnFelt = false,
): React.CSSProperties {
  const eastEdge = 'var(--trick-slot-landscape-east-edge, 14px)';
  const cardHw = 'var(--trick-slot-landscape-card-half-w, 21px)';
  const cardHh = 'var(--trick-slot-landscape-card-half-h, 31px)';
  const trumpReserve = 'var(--trick-slot-landscape-trump-reserve, 0px)';
  const hw = centerOnFelt
    ? `max(48px, calc((100% - ${trumpReserve}) / 2 - ${eastEdge} - ${cardHw}))`
    : 'var(--trick-slot-landscape-half-w, 74px)';
  const nsEdge = `var(--trick-slot-landscape-ns-edge, calc(${eastEdge} + ${cardHh}))`;
  const eastCenter = `calc(${eastEdge} + ${cardHw})`;
  const midRight = `calc(${eastEdge} + ${cardHw} + ${hw})`;
  const westRight = `calc(${eastEdge} + ${cardHw} + 2 * ${hw})`;
  if (playerCount === 3) {
    /* Треугольник: боковой (2) слева-сверху, напротив (1) справа-сверху — как у Юга. */
    switch (playerIdx) {
      case 2:
        return {
          ...base,
          right: westRight,
          top: nsEdge,
          transform: 'translate(50%, -50%)',
        };
      case 1:
        return {
          ...base,
          right: eastCenter,
          top: nsEdge,
          transform: 'translate(50%, -50%)',
        };
      case 0:
        return { ...base, right: midRight, bottom: nsEdge, transform: 'translate(50%, 50%)' };
      default:
        return { ...base, right: midRight, bottom: nsEdge, transform: 'translate(50%, 50%)' };
    }
  }
  switch (playerIdx) {
    case 3:
      return { ...base, right: eastCenter, top: '50%', transform: 'translate(50%, -50%)' };
    case 2:
      return { ...base, right: westRight, top: '50%', transform: 'translate(50%, -50%)' };
    case 1:
      return { ...base, right: midRight, top: nsEdge, transform: 'translate(50%, -50%)' };
    case 0:
      return { ...base, right: midRight, bottom: nsEdge, transform: 'translate(50%, 50%)' };
    default:
      return { ...base, right: eastCenter, top: '50%', transform: 'translate(50%, -50%)' };
  }
}

function getTrickCardSlotStyle(
  playerIdx: number,
  isMobileOrTablet: boolean,
  isMobileLandscape = false,
  playerCount: PlayerCount = 4,
  /** Mid 601–899: центрировать ромб/треугольник на сукне. */
  centerLandscapeOnFelt = false,
): React.CSSProperties {
  const base: React.CSSProperties = {
    position: 'absolute',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    pointerEvents: 'none',
  };
  if (isMobileLandscape) {
    return getTrickLandscapeSlotStyle(playerIdx, base, playerCount, centerLandscapeOnFelt);
  }
  if (isMobileOrTablet) {
    const hw = 'var(--trick-slot-half-w, 26px)';
    const hh = 'var(--trick-slot-half-h, 38px)';
    const g = 'var(--trick-slot-gap, 2px)';
    const gridX = 'var(--trick-slot-grid-offset-x, 0)';
    const mobileBase = { ...base, left: '50%', top: '50%' };
    if (playerCount === 3) {
      const x = 'var(--trick-slot-three-x, 52px)';
      const y = 'var(--trick-slot-three-y, 44px)';
      switch (playerIdx) {
        case 2:
          return {
            ...mobileBase,
            transform: `translate(calc(-50% - ${x} + ${gridX}), calc(-50% - ${y}))`,
          };
        case 1:
          return {
            ...mobileBase,
            transform: `translate(calc(-50% + ${x} + ${gridX}), calc(-50% - ${y}))`,
          };
        case 0:
          return {
            ...mobileBase,
            transform: `translate(calc(-50% + ${gridX}), calc(-50% + ${y}))`,
          };
        default:
          return {
            ...mobileBase,
            transform: `translate(calc(-50% + ${gridX}), calc(-50% + ${y}))`,
          };
      }
    }
    switch (playerIdx) {
      case 2: return { ...mobileBase, transform: `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(-50% - ${hh} - ${g}))` };
      case 1: return { ...mobileBase, transform: `translate(calc(${g} + ${gridX}), calc(-50% - ${hh} - ${g}))` };
      case 3: return { ...mobileBase, transform: `translate(calc(${g} + ${gridX}), calc(${g}))` };
      case 0: return { ...mobileBase, transform: `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(${g}))` };
      default: return { ...mobileBase, transform: `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(${g}))` };
    }
  }
  const offsetEdge = 'var(--trick-slot-offset-edge, 17px)';
  const offsetWestEast = 'var(--trick-slot-offset-west-east, 101px)';
  const nsOffset = 'var(--trick-slot-ns-offset-x, 28px)';
  const nsSpread = 'var(--trick-slot-ns-spread-extra, 0px)';
  const seNudge = 'var(--trick-slot-south-east-nudge-x, 0px)';
  /** ПК · 3: как у четверых по бокам — Запад=2, Восток=1 (Север нет). */
  if (playerCount === 3) {
    const clusterShift = 'var(--trick-slot-cluster-shift-x, 0px)';
    switch (playerIdx) {
      case 2:
        return {
          ...base,
          left: `calc(${offsetWestEast} + ${clusterShift})`,
          top: '50%',
          transform: 'translateY(-50%)',
        };
      case 1:
        return {
          ...base,
          right: `calc(${offsetWestEast} - ${clusterShift})`,
          top: '50%',
          transform: 'translateY(-50%)',
        };
      case 0:
        return {
          ...base,
          bottom: offsetEdge,
          left: '50%',
          transform: `translateX(calc(-50% + ${clusterShift}))`,
        };
      default:
        return {
          ...base,
          bottom: offsetEdge,
          left: '50%',
          transform: `translateX(calc(-50% + ${clusterShift}))`,
        };
    }
  }
  switch (playerIdx) {
    case 0:
      return {
        ...base,
        bottom: offsetEdge,
        left: '50%',
        transform: `translateX(calc(-50% + ${nsOffset} + ${nsSpread} + ${seNudge}))`,
      };
    case 1:
      return {
        ...base,
        top: offsetEdge,
        left: '50%',
        transform: `translateX(calc(-50% - ${nsOffset} - ${nsSpread}))`,
      };
    case 2: return { ...base, left: offsetWestEast, top: '50%', transform: 'translateY(-50%)' };
    case 3:
      return {
        ...base,
        right: `calc(${offsetWestEast} - ${seNudge})`,
        top: '50%',
        transform: 'translateY(-50%)',
      };
    default: return { ...base, bottom: offsetEdge, left: '50%', transform: 'translateX(-50%)' };
  }
}

/** Индекс игрока, чья карта пока наивысшая во взятке (или null) */
function getCurrentTrickLeaderIndex(state: GameState): number | null {
  if (state.phase !== 'playing' || state.currentTrick.length === 0) return null;
  const n = playerCountOf(state);
  const winnerOffset = getTrickWinner(
    state.currentTrick,
    state.currentTrick[0].suit,
    state.trump ?? undefined
  );
  return getTrickPlayerIndex(state.trickLeaderIndex, winnerOffset, n);
}

/** Трансформ слота — для анимации сбора карт к победителю; те же позиции, что и getTrickCardSlotStyle */
function getTrickSlotTransform(
  playerIdx: number,
  isMobileOrTablet: boolean,
  isMobileLandscape = false,
  playerCount: PlayerCount = 4,
): string {
  if (isMobileLandscape) {
    return 'translate(-50%, -50%)';
  }
  if (isMobileOrTablet) {
    const hw = 'var(--trick-slot-half-w, 26px)';
    const hh = 'var(--trick-slot-half-h, 38px)';
    const g = 'var(--trick-slot-gap, 2px)';
    const gridX = 'var(--trick-slot-grid-offset-x, 0)';
    if (playerCount === 3) {
      const x = 'var(--trick-slot-three-x, 52px)';
      const y = 'var(--trick-slot-three-y, 44px)';
      switch (playerIdx) {
        case 2:
          return `translate(calc(-50% - ${x} + ${gridX}), calc(-50% - ${y}))`;
        case 1:
          return `translate(calc(-50% + ${x} + ${gridX}), calc(-50% - ${y}))`;
        case 0:
          return `translate(calc(-50% + ${gridX}), calc(-50% + ${y}))`;
        default:
          return `translate(calc(-50% + ${gridX}), calc(-50% + ${y}))`;
      }
    }
    switch (playerIdx) {
      case 2: return `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(-50% - ${hh} - ${g}))`;
      case 1: return `translate(calc(${g} + ${gridX}), calc(-50% - ${hh} - ${g}))`;
      case 3: return `translate(calc(${g} + ${gridX}), calc(${g}))`;
      case 0: return `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(${g}))`;
      default: return `translate(calc(-50% - ${hw} - ${g} + ${gridX}), calc(${g}))`;
    }
  }
  if (playerCount === 3) {
    const clusterShift = 'var(--trick-slot-cluster-shift-x, 0px)';
    switch (playerIdx) {
      case 2:
      case 1:
        return 'translateY(-50%)';
      case 0:
        return `translateX(calc(-50% + ${clusterShift}))`;
      default:
        return `translateX(calc(-50% + ${clusterShift}))`;
    }
  }
  const ns = 'var(--trick-slot-ns-offset-x, 28px)';
  const nsSpread = 'var(--trick-slot-ns-spread-extra, 0px)';
  const seNudge = 'var(--trick-slot-south-east-nudge-x, 0px)';
  switch (playerIdx) {
    case 0:
      return `translate(-50%, -50%) translateY(32%) translateX(calc(${ns} + ${nsSpread} + ${seNudge}))`;
    case 1:
      return `translate(-50%, -50%) translateY(-32%) translateX(calc(-1 * (${ns} + ${nsSpread})))`;
    case 2: return 'translate(-50%, -50%) translateX(-30%)';
    case 3:
      return `translate(-50%, -50%) translateX(calc(30% + ${seNudge}))`;
    default:
      return `translate(-50%, -50%) translateY(32%) translateX(calc(${ns} + ${nsSpread} + ${seNudge}))`;
  }
}

const TRICK_COLLECT_EASE = 'cubic-bezier(0.22, 0.61, 0.36, 1)';

/** Обёртка слота при анимации сбора взятки; landscape — те же якоря, что getTrickCardSlotStyle */
function getTrickCollectSlotStyle(
  playerIdx: number,
  winnerIdx: number,
  collectToWinner: boolean,
  isMobileOrTablet: boolean,
  isMobileLandscape: boolean,
  cardCollectMs: number,
  playerCount: PlayerCount = 4,
  centerLandscapeOnFelt = false,
): React.CSSProperties {
  const slotIdx = collectToWinner ? winnerIdx : playerIdx;
  if (isMobileLandscape) {
    const collectTransition = [
      `left ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
      `top ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
      `bottom ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
      `right ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
      `transform ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
    ].join(', ');
    return {
      ...getTrickCardSlotStyle(slotIdx, isMobileOrTablet, true, playerCount, centerLandscapeOnFelt),
      /* Transition всегда — иначе смена transition+transform в одном кадре глотает полёт. */
      transition: collectTransition,
    };
  }
  return {
    position: 'absolute',
    left: '50%',
    top: '50%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    pointerEvents: 'none',
    transform: getTrickSlotTransform(slotIdx, isMobileOrTablet, false, playerCount),
    /* Transition всегда — иначе смена transition+transform в одном кадре глотает полёт. */
    transition: `transform ${cardCollectMs}ms ${TRICK_COLLECT_EASE}`,
  };
}

