/** Не смешивать borderRadius shorthand с longhand углов — иначе React warning при смене веток TrickSlotsDisplay. */
function resolveTrickWrapStyle(style: CSSProperties): CSSProperties {
  if (
    style.borderTopLeftRadius != null ||
    style.borderTopRightRadius != null ||
    style.borderBottomLeftRadius != null ||
    style.borderBottomRightRadius != null
  ) {
    const { borderRadius: _omit, ...rest } = style;
    return rest;
  }
  return style;
}

/**
 * Lab chrome (`mop-panel--lab-chrome`) рисует заливку/рамку через CSS vars + ::before.
 * Inline border/background/boxShadow с базы trickCircles иначе остаются и дают «голые» цифры
 * или старую оранжевую рамку поверх сдающего.
 */
function omitInlineTrickPanelChrome(style: CSSProperties): CSSProperties {
  const {
    border: _border,
    borderColor: _borderColor,
    borderWidth: _borderWidth,
    borderStyle: _borderStyle,
    background: _background,
    backgroundImage: _backgroundImage,
    boxShadow: _boxShadow,
    ...rest
  } = style;
  return rest;
}

function withMobileOrderLabChrome(
  base: CSSProperties,
  mopWrapStyle: CSSProperties | null | undefined,
): CSSProperties {
  if (!mopWrapStyle) return base;
  return omitInlineTrickPanelChrome({ ...base, ...mopWrapStyle });
}

